function esc(s){return String(s??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[m]))}async function api(url,o={}){const r=await fetch(url,{headers:{'Content-Type':'application/json'},...o});if(!r.ok)throw new Error((await r.json()).error||'Request failed');return r.json()}async function load(){state.db=await api('/api/state');render()}function setLang(v){state.lang=v;localStorage.setItem('lang',v);render()}function setRole(r){state.role=r;state.screen='register';render()}function nav(s){state.screen=s;render()}
function shell(c){return `<header class="top"><div class="brand">🌾 ${t('brand')}</div><select class="lang" aria-label="${t('choose')}" onchange="setLang(this.value)"><option value="en" ${state.lang==='en'?'selected':''}>English</option><option value="te" ${state.lang==='te'?'selected':''}>తెలుగు</option><option value="hi" ${state.lang==='hi'?'selected':''}>हिन्दी</option><option value="ta" ${state.lang==='ta'?'selected':''}>தமிழ்</option><option value="kn" ${state.lang==='kn'?'selected':''}>ಕನ್ನಡ</option><option value="mr" ${state.lang==='mr'?'selected':''}>मराठी</option></select></header><main class="wrap">${c}</main><footer class="footer">${t('brand')} • ${t('tag')}</footer>`}

